SELECT ID_ACTA_SUSTENTO, ORDEN_COMPRA_ID, NUMERO_ACTA_SUSTENTO, PROVEEDOR_ID, FECHA_REGISTRO, ESTADO, CODIGO_SAP_EM, CODIGO_SAP_HES, ANIO_ACTA_SUSTENTO, p.RAZON_SOCIAL FROM ACTA_SUSTENTO A INNER JOIN PROVEEDOR p ON A.PROVEEDOR_ID = p.ID_PROVEEDOR
WHERE A.ESTADO = 1
AND A.NUMERO_ACTA_SUSTENTO LIKE '%'||#{numeroActaSustento}||'%'
AND A.ANIO_ACTA_SUSTENTO = #{annioActa}
AND A.PROVEEDOR_ID = #{idProveedor}
AND p.RAZON_SOCIAL LIKE '%'||UPPER(#{nombreProveedor})||'%'
ORDER BY A.NUMERO_ACTA_SUSTENTO DESC
LIMIT #{nroRegistros} OFFSET #{paginaMostrar}

SELECT ID_ACTA_SUSTENTO, ORDEN_COMPRA_ID, NUMERO_ACTA_SUSTENTO, PROVEEDOR_ID, A.FECHA_REGISTRO, ESTADO, CODIGO_SAP_EM, CODIGO_SAP_HES, ANIO_ACTA_SUSTENTO, p.RAZON_SOCIAL as RAZON_SOCIAL_P, p.EMAIL as EMAIL_P, OC.NUMERO_ORDEN_COMPRA FROM ACTA_SUSTENTO A INNER JOIN PROVEEDOR p ON A.PROVEEDOR_ID = p.ID_PROVEEDOR INNER JOIN ORDEN_COMPRA OC ON A.ORDEN_COMPRA_ID = OC.ID_ORDEN_COMPRA
WHERE A.ESTADO in(2,4,5)
AND A.NUMERO_ACTA_SUSTENTO LIKE '%'||#{numeroActa}||'%'
AND A.ANIO_ACTA_SUSTENTO = #{annioActa}
AND A.PROVEEDOR_ID = #{idProveedor}
AND p.RAZON_SOCIAL LIKE '%'||UPPER(#{nombreProveedor})||'%'
ORDER BY A.NUMERO_ACTA_SUSTENTO DESC
LIMIT #{nroRegistros} OFFSET #{paginaMostrar}

SELECT ID_ACTA_SUSTENTO, ORDEN_COMPRA_ID, NUMERO_ACTA_SUSTENTO, PROVEEDOR_ID, FECHA_REGISTRO, ESTADO, CODIGO_SAP_EM, CODIGO_SAP_HES, ANIO_ACTA_SUSTENTO, p.RAZON_SOCIAL as RAZON_SOCIAL_P, p.EMAIL as EMAIL_P FROM ACTA_SUSTENTO A INNER JOIN PROVEEDOR p ON A.PROVEEDOR_ID = p.ID_PROVEEDOR
WHERE A.ESTADO in(3)
AND A.NUMERO_ACTA_SUSTENTO = #{numeroActaSustento}
AND A.ANIO_ACTA_SUSTENTO = #{annioActa}
AND A.PROVEEDOR_ID = #{idProveedor}
AND p.RAZON_SOCIAL LIKE '%'||UPPER(#{nombreProveedor})||'%'
ORDER BY A.NUMERO_ACTA_SUSTENTO DESC
LIMIT #{nroRegistros} OFFSET #{paginaMostrar}
